input.command:
python -m unittest discover -s tests -t . 2>&1 | tail -4; python -c "
from miniconf.loader import load
c=load('examples/service.conf'); print(vars(c))
import os
os.makedirs('.tmpinc',exist_ok=True)
open('.tmpinc/a','w').write('@include b\n'); open('.tmpinc/b','w').write('@include a\n')
try: load('.tmpinc/a')
except Exception as e: print(type(e),e)
open('.tmpinc/c','w').write('@include nope\n')
try: load('.tmpinc/c')
except Exception as e: print(type(e),e)
"; rm -rf .tmpinc

